"""Bounded PSOLA control experiment; waveform interiors are not generated by a net.

Pitch and duration tiers are applied in one Praat resynthesis pass. This is a
host reference implementation, not a P4 port or a perceptual quality guarantee.
"""
import numpy as np
import parselmouth
from parselmouth.praat import call


def render_controls(audio,rate,pitch_times=None,pitch_hz=None,duration_times=None,duration_factors=None,
                    pitch_limit_semitones=2.,duration_limits=(.8,1.25),clip_pitch=True):
    if audio.dtype!=np.int16 or audio.ndim!=1 or len(audio)<rate*.08:
        raise ValueError('Controls require mono PCM16 and sufficient pitch context')
    duration=len(audio)/rate
    factors=None if duration_factors is None else np.asarray(duration_factors,np.float64)
    if factors is not None:
        times=np.asarray(duration_times,np.float64)
        if (times.ndim!=1 or times.shape!=factors.shape or len(times)<2 or
                not np.isfinite(times).all() or not np.isfinite(factors).all() or
                np.any(np.diff(times)<=0) or times[0]<0 or times[-1]>duration+1e-6 or
                factors.min()<duration_limits[0] or factors.max()>duration_limits[1]):
            raise ValueError('Invalid or excessive duration control')
    if pitch_hz is None and (factors is None or np.all(factors==1)):
        return audio.copy(),dict(method='identity',modified=False,rate=rate)
    sound=parselmouth.Sound(audio.astype(np.float64)/32768,rate)
    manipulation=call(sound,'To Manipulation',.005,75,600)
    clipped_pitch=0
    if pitch_hz is not None:
        pt=np.asarray(pitch_times,np.float64);hz=np.asarray(pitch_hz,np.float64)
        if (pt.ndim!=1 or pt.shape!=hz.shape or len(pt)<2 or np.any(np.diff(pt)<=0) or
                not np.isfinite(pt).all() or not np.isfinite(hz).all() or
                pt[0]<0 or pt[-1]>duration+1e-6 or hz.min()<75 or hz.max()>600):
            raise ValueError('Invalid pitch control')
        source=sound.to_pitch_ac(time_step=.005,pitch_floor=75,pitch_ceiling=600)
        source_hz=source.selected_array['frequency'];valid=source_hz>0
        if valid.sum()<3:raise ValueError('Insufficient voiced source for reliable pitch control')
        original=np.interp(pt,source.xs()[valid],source_hz[valid])
        # Initial experiment: at most +/- two semitones. Large corrections
        # should trigger source reselection, not a forced tone conversion.
        ratio=np.log(hz/original);limit=pitch_limit_semitones*np.log(2)/12
        clipped_pitch=int(np.sum(abs(ratio)>limit))
        if clipped_pitch and not clip_pitch:
            raise ValueError('Requested pitch target exceeds declared renderer range; reselect source')
        if clip_pitch:
            hz=original*np.exp(np.clip(ratio,-limit,limit))
        tier=call(manipulation,'Extract pitch tier')
        call(tier,'Remove points between',0,duration)
        for t,f in zip(pt,hz):call(tier,'Add point',float(t),float(f))
        call([tier,manipulation],'Replace pitch tier')
    if factors is not None:
        tier=call('Create DurationTier','duration',0,duration)
        for t,f in zip(times,factors):call(tier,'Add point',float(t),float(f))
        call([tier,manipulation],'Replace duration tier')
    result=call(manipulation,'Get resynthesis (overlap-add)')
    values=result.values[0]*32768
    if not np.isfinite(values).all() or values.max()>32767 or values.min()<-32768:
        raise ValueError('Resynthesis clipping/nonfinite output; no normalization applied')
    return np.rint(values).astype(np.int16),dict(method='praat_psola',modified=True,
        rate=rate,input_samples=len(audio),output_samples=len(values),
        pitch_points_limited=clipped_pitch,pitch_limit_semitones=pitch_limit_semitones,
        duration_factor_limits=list(duration_limits),pitch_target_clipping=clip_pitch,
        joint_pitch_duration_pass=True,
        waveform_generator=False,quality_passed=False)
